SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷76·晋高祖纪·天福二年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5bcdd3b7314e12d7264f468cb5a94810f96be300/content/books/zizhi-tongjian/vol-281/year-0937/part-08/sources/library/jiuwudaishi-076-november/source.txt", "note": "《旧五代史》卷76·晋高祖纪·天福二年十一月，段落 jiu-wudaishi-205deb4a7860-p001907；已核上下文及传主，纸本及异文待核。", "id": "96ac9c60-fbcd-5e7f-94f8-627514fa5ca3"}, {"title": "旧五代史·卷97·李金全传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5bcdd3b7314e12d7264f468cb5a94810f96be300/content/books/zizhi-tongjian/vol-281/year-0937/part-08/sources/library/jiuwudaishi-097-hu-jia/source.txt", "note": "《旧五代史》卷97·李金全传，段落 jiu-wudaishi-205deb4a7860-p002384；已核上下文及传主，纸本及异文待核。", "id": "e0c21416-750e-5959-934a-31ccab3c4bd5"}, {"title": "辽史·卷4·太宗纪·会同元年十一月", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5bcdd3b7314e12d7264f468cb5a94810f96be300/content/books/zizhi-tongjian/vol-281/year-0937/part-08/sources/library/liaoshi-004-huitong/source.txt", "note": "《辽史》卷4·太宗纪·会同元年十一月，段落 liaoshi-7cd182a20e67-p000472；已核上下文及传主，纸本及异文待核。", "id": "46d1d50f-d2f8-50d9-acc2-41480485080c"}, {"title": "辽史·卷76·赵延寿传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5bcdd3b7314e12d7264f468cb5a94810f96be300/content/books/zizhi-tongjian/vol-281/year-0937/part-08/sources/library/liaoshi-076-zhao-yanshou/source.txt", "note": "《辽史》卷76·赵延寿传，段落 liaoshi-7cd182a20e67-p005110；已核上下文及传主，纸本及异文待核。", "id": "eca0604c-164e-538e-b43f-f41da30da6d8"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/his