INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐氏（杨琏妃）", "aliases": ["徐知诰女"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐知诰（后来的李昪）的女儿，937年嫁给吴太子杨琏。此段没有记载她的名字。", "biography": null, "status": "draft", "id": "aaef797d-c1e0-5687-85cb-0a95bb652cb3"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}, {"name": "胡汉筠", "aliases": ["胡漢筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李金全的亲近吏员。受任中门使，掌管安远军府事务。史书记载他遭朝廷召调后劝李金全背离朝廷，又谋害反对自己的庞令图和接替他的贾仁沼。各次行动的具体日期并非全都记明。", "biography": null, "status": "draft", "id": "671f993a-ecbf-5fc0-8a33-2dfa8daa2b04"}, {"name": "贾仁沼", "aliases": ["賈仁沼", "贾仁绍", "賈仁紹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋吏员。石敬瑭派他接替胡汉筠，后来被胡汉筠毒杀。具体死亡年份此段未载。", "biography": null, "status": "draft", "id": "90f17e0d-51f1-5fdf-a633-c2210c39d294"}, {"name": "庞令图", "aliases": ["龐令圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李金全的故人，曾多次劝他接受贾仁沼并替换胡汉筠。胡汉筠派人在夜间翻墙杀害庞令图一家，具体发生日期未载。", "biography": null, "status": "draft", "id": "91a57fce-276a-51f6-858a-1d6c1e3e96d7"}, {"name": "张纬（李金全推官）", "aliases": ["张纬", "張緯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李金全属下推官。史书记载他与胡汉筠互相勾结，以奉承的方式影响李金全，具体起止时间未载。", "biography": null, "status": "draft", "id": "804e88ac-166b-5b44-9fc8-a1db17078f27"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "徐景通改名为璟", "start_year": 937, "end_year": 937, "time_original": "937年十一月乙卯", "dynasty": "五代十国", "description": "徐景通改名为璟。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5f2e7c0b-a754-50c9-a365-b53395ab69db"}, {"title": "徐诰赐杨琏妃永兴公主称号", "start_year": 937, "end_year": 937, "time_original": "937年十一月乙卯条下", "dynasty": "五代十国", "description": "徐诰赐杨琏妃永兴公主称号。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "25707f04-6fb2-50b0-a72d-6fbce5276b2e"}, {"title": "杨琏妃听到别人称自己为公主便流泪辞谢", "start_year": null, "end_year": null, "time_original": "获赐永兴公主称号之后，具体起止日期未载", "dynasty": "五代十国", "description": "杨琏妃听到别人称自己为公主便流泪辞谢。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "825a0077-3570-54e5-a97e-da1730bc4534"}, {"title": "徐诰封徐景遂为吉王", "start_year": 937, "end_year": 937, "time_original": "937年十一月戊午", "dynasty": "五代十国", "description": "徐诰封徐景遂为吉王。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "84a47570-2420-59b6-a9aa-5d3df556b679"}, {"title": "徐诰封徐景达为寿阳公", "start_year": 937, "end_year": 937, "time_original": "937年十一月戊午", "dynasty": "五代十国", "description": "徐诰封徐景达为寿阳公。", "phases": [], "loca